#include <stdio.h>
#include <string.h>
#include <stddef.h>

#define MAX_LEN 0x401
#define TABLE_SIZE 256

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    if (strlen(s1) >= MAX_LEN || strlen(s2) >= MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    int cnt1[TABLE_SIZE] = {0};
    int cnt2[TABLE_SIZE] = {0};
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c >= 'A' && c <= 'Z')
            c += ('a' - 'A');
        cnt1[c]++;
    }
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c >= 'A' && c <= 'Z')
            c += ('a' - 'A');
        cnt2[c]++;
    }
    int anagram = 1;
    for (int i = 0; i < TABLE_SIZE; ++i) {
        if (cnt1[i] != cnt2[i]) {
            anagram = 0;
            break;
        }
    }
    puts(anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
